      </div>
    </section>
  );
}

interface HourSelectProps {
  label: string;
  icon: React.ReactNode;
  value: number;
  format: Settings["timeFormat"];
  onChange: (hour: number) => void;
}

function HourSelect({ label, icon, value, format, onChange }: HourSelectProps) {
