import type { Mode } from "../types";

export function Legend({ mode, referenceName }: { mode: Mode; referenceName: string }) {
  return (
    <footer className="legend">
      <ul className="legend__keys">
        <li>
          <span className="swatch swatch--overlap" /> Overlap
        </li>
