dev-browser --headless <<'EOF'
const page = await browser.getPage("tzm");
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector(".mgrid");
await page.selectOption('.hour-select:first-of-type select', '22');
await page.selectOption('.hour-select:last-of-type select', '6');
await page.click('button[role="radio"]:has-text("24h")');
await page.waitForTimeout(300);
const p = await saveScreenshot(await page.screenshot({ fullPage: false }), "mobile2.png");
console.log(JSON.stringify({ p, summary: await page.textContent(".summary"), hint: await page.textContent(".controls") }));
EOF
cp ~/.dev-browser/tmp/mobile2.png .verify/

